%% NEURON_THERMO_MODELS.M
% Hodgkin-Huxley (HH) model vs. Heimburg-Jackson soliton model of the nerve pulse,
% with thermodynamic analysis for BME 313.
%
% Course guidelines addressed (3 of 5):
%   (i)   PV-type diagrams -> lateral pressure (pi) vs. area (A) diagrams, the 2-D
%         analogue of P-V, for the soliton/membrane model: reversible isotherms,
%         the reversible pulse path, and an irreversible (hysteresis) loop.
%   (ii)  Enthalpy / entropy / free-energy balances ->
%           HH:      heat dissipated + entropy generated by each ionic current
%           Soliton: H, S, G, cp of the lipid melting transition; heat released
%                    and absorbed as the pulse compresses the membrane
%   (iii) Free energy of reactions and equilibria ->
%           HH:      Nernst equilibria, dG of ion movement, Na/K pump vs ATP dG
%           Soliton: dG and K_eq of the gel <-> fluid "reaction"
%
% Requires: base MATLAB (R2016b+ for local functions in scripts). No toolboxes.
% Run time: roughly 10-60 s (the soliton PDE is the slow part).
%
% NOTE: parameter values are literature-style but not verified against the
% papers. Anything marked ASSUMED is a tunable choice, not a measured value.

clear; clc; close all;

% These are the constants used in the calculations. 
R = 8.314;       % J/(mol K); Ideal gas constant
F = 96485;       % q/mol; Faraday's constant for electrical work/energy, q = charge.
NA = 6.0221e23;    % 1/mol; Avogadro's number
% eventually, we will use these constants to calculate things like energy, entropy in both models. 

% Here, we begin formulating the mathematical models for the Hodgkin-Huxley model. 

% initializing variables
T1   = 273.15 + 6.3;                  %  K (squid-axon temperature, from the original 1952 Hogskin-Huxley paper)
Q10  = 3; % temperature coefficient; represents a rate change per 10 degrees
phi  = Q10^((T1 - 273.15 - 6.3)/10);  % Phi is the scaling multiplier applied to opening and closing rates of channels based on the temperature. 

% Squid-axon concentrations to Nernst potentials
Nao = 440; % sodium concentrations
Nai = 50;
Ko  = 20;  % pottasium concentrations
Ki  = 400;

% nerst equations - calculates equilibrium potentials based on Na+ and K+ ion concentrations.
ENa = 1e3*R*T1/F*log(Nao/Nai); % mV, should be approx. 55mV
EK  = 1e3*R*T1/F*log(Ko/Ki);   % mV, should be approx. 72 mV
EL  = -54.387; % mV, leaky channel reversal potential, fitted 

 
% this is the struct that holds the membrane capacitances (Cm) and max conductances (gNa, gK, gL) as well as other variables described above
P = struct('Cm',1,'gNa',120,'gK',36,'gL',0.3,'ENa',ENa,'EK',EK,'EL',EL,'phi',phi);

% ODE
V0 = -65; % initial condition; the standard resting membrane potential for a neuron is -65 mV. 
[am,bm,an,bn,ah,bh] = hh_rates(V0); % steady state opening and closing rates for resting membrane potential V0.
y0 = [V0; am/(am+bm); an/(an+bn); ah/(ah+bh)]; % this is the y0 vector.....

% Stimulus: 15 uA/cm^2 for 1 ms starting at t = 10 ms (integrated in segments)
% instead of simulating the entire timeline, code is broken into segments to apply the stimulus like this:
% 10 ms rest, 1ms stimulus, 29 ms rest. 
% 
segs = [0 10 0; 10 11 15; 11 40 0];   % segs is an array that defines the stimulus protocol of this Hodgkin-huxley model.
% from 0-10 ms, there is no stimulus (at rest)
% from 10-11 ms, a 15 uA/cm^2 stimulus is injected 
% from 11-40 ms, there is no stimulus (at rest)
opts = odeset('RelTol',1e-8,'AbsTol',1e-10,'MaxStep',0.02); % odeset is a functino that allows you to pass your own parameters through the ODE solver. 
% the relative tolerance is set to 1e-8, the absolute tolerance is set to 1e-10, and the maximum step size is set to 0.02 ms.
t = []; 
Y = []; 
Iext = [];  %initialize empty arrays to hole time, state, and external current numbers.

% this for loop goes through stimulus segments and solves the ODE for each segment. 
for s = 1:size(segs,1)
    [ts,ys] = ode45(@(tt,yy) hh_rhs(tt,yy,segs(s,3),P), segs(s,1:2), y0, opts);
        % ode45 solves the hodgkin-huxley ODE, that are defined in the function hh_rhs
    if s > 1, ts(1) = []; % this prevents duplicate time points at the segment boundaries.
        ys(1,:) = []; 
    end
    t = [t; ts]; Y = [Y; ys]; Iext = [Iext; segs(s,3)*ones(size(ts))]; %#ok<AGROW> %variable chnages size on every loop, need this comment to suppress error
    y0 = ys(end,:)'; % final state of segment = initial state for next segment
end

% state variables V, m, n, h are extracted from the solution array Y
V = Y(:,1); 
m = Y(:,2); 
n = Y(:,3); 
h = Y(:,4);


% calculating the time-varying conductances based on gating probabilities
% Currents (uA/cm^2, outward positive) and conductances (mS/cm^2)
gNat = P.gNa*m.^3.*h;  
gKt = P.gK*n.^4;  
gLt = P.gL*ones(size(t));

% calculate ion currents with Ohm's law, I = g(V-E); V = IR
INa = gNat.*(V-ENa);   
IK = gKt.*(V-EK);  
IL = gLt.*(V-EL);



%% power dissipated as heat by ions flowing down their electrochemical gradients, P = IV
% Each ionic current dissipates free energy of the gradient as heat:
%   P_i = I_i (V - E_i) = g_i (V-E_i)^2 >= 0     [uA*mV = nW per cm^2]
PNa = INa.*(V-ENa);  
PK = IK.*(V-EK);  
PL = IL.*(V-EL);

% integrate power over time to get t0tal heat dissipated
QNa = cumtrapz(t,PNa); 
QK = cumtrapz(t,PK); 
QL = cumtrapz(t,PL);   % pJ/cm^2 (nW*ms)


Qtot = QNa + QK + QL; % total heat
Sgen = Qtot/T1; % entropy generate = heat/temperature; (pJ/(cm^2 K))
Ecap = 0.5*P.Cm*(V.^2); % energy stored in the membrance capacitance 

%% gibbs free energy of ion movement: dG = F*(V-E)
% dG for moving one mole of a cation INTO the cell: dG = F (V - E)
dG_Na = F*(V-ENa)*1e-6;   % kJ/mol
dG_K = F*(V-EK)*1e-6;    % kJ/mol


iRest = find(t >= 9, 1);  % line for finding the exact resting potential before stimulus is applied.
Vrest = V(iRest); % mV, just before stimulus
Vr = Vrest*1e-3; % convert to volts

% this equation represents the free energy required for tne Na/K pump, where 3 Na+ moves against gradient, 2 K+ against gradient.
%  ....
dG_pump = 3*( R*T1*log(Nao/Nai) - F*Vr ) + 2*( R*T1*log(Ki/Ko) + F*Vr );  % J/mol
% ATP hydrolysis (ASSUMED standard dG0' and cell concentrations)
dG0 = -30.5e3; % standard energy and concentration of ATP hydrolysis, J/mol
ATP = 5e-3; 
ADP = 50e-6; 
Pi = 1e-3; % ??????? J/mol, M
dG_ATP = dG0 + R*T1*log(ADP*Pi/ATP);  % formula for free energy of atp hydrolysis; J/mol
Keq_ATP = exp(-dG0/(R*T1)); %equilibrium constant M (ADP*Pi/ATP at equilibrium)
% Na gradient at which the pump stalls (dG_pump = -dG_ATP)
r_stall = exp((abs(dG_ATP) + F*Vr - 2*R*T1*log(Ki/Ko))/(3*R*T1));  % ratio where pump runs out of energy is Nao/Nai

% Na+ entering per spike, and the ATP needed to restore it
iWin = t >= 10 & t <= 20;
Na_in_pmol = -trapz(t(iWin),INa(iWin))*1e-9/F*1e12; % charge to moles --  uA*ms = nC; -> pmol/cm^2
ATP_pmol   = Na_in_pmol/3; % 1 atp per 3 Na+ pumped out
E_ATP_pJ   = ATP_pmol*abs(dG_ATP); % total energy necessary to restore gradients; pmol * J/mol = pJ/cm^2


% PRINTING INFORMATION / RESULTS
fprintf('\n========== HODGKIN-HUXLEY (T = %.2f K) ==========\n',T1);
fprintf('E_Na = %+.1f mV,  E_K = %+.1f mV,  rest V = %.1f mV\n',ENa,EK,Vrest);
fprintf('Equilibrium (Nernst) internal conc. at rest potential:\n');
fprintf('   Na_i,eq = %.1f mM (actual %.0f mM)   K_i,eq = %.0f mM (actual %.0f mM)\n', ...
        Nao*exp(-F*Vr/(R*T1)), Nai, Ko*exp(-F*Vr/(R*T1)), Ki);
fprintf('dG(Na+ in) at rest = %+.2f kJ/mol,  dG(K+ in) at rest = %+.2f kJ/mol\n', ...
        F*(Vrest-ENa)*1e-6, F*(Vrest-EK)*1e-6);
fprintf('Pump work needed (3Na out, 2K in) = %.1f kJ/mol; dG_ATP = %.1f kJ/mol\n', ...
        dG_pump*1e-3, dG_ATP*1e-3);
fprintf('Pump stalls at Na_o/Na_i = %.3g (actual %.2f);  K_eq(ATP hydrolysis) = %.3g M\n', ...
        r_stall, Nao/Nai, Keq_ATP);
fprintf('Per spike: Na+ in = %.3f pmol/cm^2, heat dissipated = %.4f pJ/cm^2\n', ...
        Na_in_pmol, Qtot(end)-Qtot(find(t>=10,1)));
fprintf('           entropy generated = %.2e pJ/(cm^2 K), ATP-equivalent cost = %.4f pJ/cm^2\n', ...
        Sgen(end)-Sgen(find(t>=10,1)), E_ATP_pJ);

%%  Hodgkin-Huxley figures
figure('Name','HH: dynamics','Position',[50 50 1100 750]);
subplot(2,2,1); plot(t,V,'k','LineWidth',1.5); hold on;
yline(ENa,'--r','E_{Na}'); yline(EK,'--b','E_K');
xlabel('t (ms)'); ylabel('V (mV)'); title('Membrane potential'); grid on;
subplot(2,2,2); plot(t,m,t,h,t,n,'LineWidth',1.3);
legend('m','h','n'); xlabel('t (ms)'); ylabel('gating variable'); title('Gating kinetics'); grid on;
subplot(2,2,3); plot(t,INa,t,IK,t,IL,'LineWidth',1.3);
legend('I_{Na}','I_K','I_L'); xlabel('t (ms)'); ylabel('\muA/cm^2 (outward +)'); title('Ionic currents'); grid on;
subplot(2,2,4); plot(V,n,'k','LineWidth',1.3); xlabel('V (mV)'); ylabel('n');
title('Phase portrait (V, n)'); grid on;

figure('Name','HH: thermodynamics','Position',[100 80 1100 750]);
subplot(2,2,1); plot(t,dG_Na,t,dG_K,'LineWidth',1.5); yline(0,'k:');
legend('\DeltaG Na^+ (in)','\DeltaG K^+ (in)'); xlabel('t (ms)'); ylabel('kJ/mol');
title('(iii) Free energy of ion movement: \DeltaG = F(V - E_{ion})'); grid on;
subplot(2,2,2); plot(t,PNa,t,PK,t,PL,'LineWidth',1.3);
legend('Na','K','Leak'); xlabel('t (ms)'); ylabel('nW/cm^2'); title('(ii) Dissipation rate  I_i (V - E_i)'); grid on;
subplot(2,2,3); plot(t,QNa,t,QK,t,QL,t,Qtot,'k','LineWidth',1.3);
legend('Na','K','Leak','Total'); xlabel('t (ms)'); ylabel('pJ/cm^2'); title('Cumulative heat dissipated'); grid on;
subplot(2,2,4); plot(t,Sgen,'m','LineWidth',1.5); xlabel('t (ms)'); ylabel('pJ/(cm^2 K)');
title('Cumulative entropy generation (never decreases)'); grid on;


%%  PART 2: SOLITON MODEL (Heimburg & Jackson) + LIPID-TRANSITION THERMODYNAMICS
% --- 2a. Two-state (gel <-> fluid) cooperative melting model for the membrane ---

% Really need to better understand the parameters I'm using here. 
T0 = 310.15; % Kelvin, body temperature (37 C)
Tm = 309.15; % Kelvin, membrane melting temperature of DPPC, the most common phospholipid
pi_ref= 30e-3;  % N/m, reference lateral pressure (ASSUMED)
dH = 36.4e3; % J/mol, transition enthalpy at pi_ref, 
dS = dH/Tm; % J/(mol K); entropy of transition where dS = dH/Tm at equlibrium
Ag = 0.48e-18*NA; % m^2/mol, gel area per lipid 0.48 nm^2
Af = 0.64e-18*NA; % m^2/mol, fluid area per lipid 0.64 nm^2 (ASSUMED)
dA = Af - Ag; % change in area per mole during melting
nco = 20; % cnumber of lipids melting together

dGt = @(Tk,pk) dH*(1-Tk./Tm) + (pk-pi_ref).*dA; % this is the free energy chanfe between gel and fluid state as a function of temperature and pressure
xf  = @(Tk,pk) 1./(1+exp(nco*dGt(Tk,pk)./(R*Tk))); % 

x0    = xf(T0,pi_ref);
Amol0 = Ag + x0*dA;                                       % m^2/mol at rest
n0    = 1/Amol0;                                          % mol lipid per m^2 membrane

%% --- (iii) soliton: free energy of the "reaction" gel <=> fluid ----------------
fprintf('\n========== SOLITON / LIPID TRANSITION ==========\n');
fprintf('dG(gel->fluid) at T0, pi_ref = %+.1f J/mol per lipid\n', dGt(T0,pi_ref));
fprintf('K_eq (per cooperative unit) = %.3g;  equilibrium fluid fraction = %.3f\n', ...
        exp(-nco*dGt(T0,pi_ref)/(R*T0)), x0);
fprintf('dTm/dpi = %.3f K per mN/m  (Clapeyron-type: dA/dS)\n', dA/dS*1e-3);

% --- 2b. Soliton PDE: u_tt = d^2/dx^2( c0^2 u + p u^2/2 + q u^3/3 ) - h u_xxxx -------
%   u = delta rho / rho0 (relative change in lateral density: u>0 = compression)
c0 = 176.6;               % m/s
p  = -16.6*c0^2;          % m^2/s^2
q  =  79.5*c0^2;          % m^2/s^2
hd = 0.2;                 % m^4/s^2 dispersion. ASSUMED: tuned so pulses are ~cm wide;
                          % the literature value may differ and gives a much narrower pulse.
Lx = 0.4;  N = 512;       % domain (m), grid points (periodic)
xg = (0:N-1)'*Lx/N;
kk = (2*pi/Lx)*[0:N/2-1, -N/2:-1]';
dealias = double(abs(kk) < (2/3)*max(abs(kk)));

Au = 0.05;                                   % pulse amplitude (ASSUMED)
vs = c0*sqrt(1 - 16.6*Au/3);                 % speed from sech^2 ansatz (ignores q term)
bw = sqrt((c0^2 - vs^2)/(4*hd));             % inverse width (1/m)
xs = 0.05;
u0  = Au*sech(bw*(xg-xs)).^2;
ut0 = real(ifft(-vs*1i*kk.*fft(u0)));        % u_t = -v u_x (right-moving)
tend = 2e-3;  tt = linspace(0,tend,1500)';

fprintf('Soliton: speed %.1f m/s, width ~%.2f cm. Solving PDE...\n', vs, 100/bw);
optS = odeset('RelTol',1e-6,'AbsTol',1e-8);
[~,YS] = ode45(@(~,y) soliton_rhs(y,kk,c0,p,q,hd,dealias,N), tt, [u0; ut0], optS);
U = YS(:,1:N);                               % rows: time, cols: space

% --- 2c. Heat released/absorbed as the pulse compresses the membrane ---------------
clip = @(z) min(max(z,1e-6),1-1e-6);
xu   = clip((Amol0./(1+U) - Ag)/dA);         % fluid fraction under local compression
qA   = n0*dH*(x0 - xu)*1e3;                  % mJ/m^2, + = heat released (fluid -> gel)

[~,it1] = min(abs(tt-1.0e-3));               % snapshot time
xp_idx  = round(0.20/Lx*N);                  % probe position x = 0.20 m
up      = U(:,xp_idx);

% --- 2d. (i) pi-A path at the probe point: reversible vs irreversible -----------------
xp     = clip((Amol0./(1+up) - Ag)/dA);
pi_rev = pi_ref + ((R*T0/nco)*log((1-xp)./xp) - dH*(1-T0/Tm))/dA;   % N/m
A_rev  = Ag + xp*dA;                                                % m^2/mol

tau = 1e-4;   % s, relaxation time of the melting transition (ASSUMED)
[~,Xirr] = ode45(@(s,xx) (xf(T0,interp1(tt,pi_rev,s,'linear','extrap')) - xx)/tau, tt, x0, optS);
A_irr = Ag + Xirr*dA;

W_rev = -trapz(A_rev,pi_rev);                % J/mol, net work on membrane over the pulse
W_irr = -trapz(A_irr,pi_rev);                % J/mol
fprintf('(i) Net work per lipid over one pulse: reversible = %.3g J/mol, irreversible = %.3g J/mol\n', ...
        W_rev, W_irr);
fprintf('    Irreversible loop dissipates heat = %.3g J/mol -> entropy generated = %.3g J/(mol K)\n', ...
        W_irr, W_irr/T0);
fprintf('(ii) Peak heat released on compression = %.3g mJ/m^2; net after pulse = %.2g mJ/m^2\n', ...
        max(qA(:,xp_idx)), qA(end,xp_idx));

% --- 2e. (ii) H, S, G, cp of the transition at fixed pi_ref ------------------------------
Tg  = linspace(300,320,2000)';
xg_ = clip(xf(Tg,pi_ref));
Hx  = xg_*dH;                                                   % J/mol
mix = -(R/nco)*(xg_.*log(xg_)+(1-xg_).*log(1-xg_));
Sx  = xg_*dS + mix;                                             % J/(mol K)
Gx  = Hx - Tg.*Sx;                                              % J/mol
cpx = gradient(Hx,Tg);                                          % J/(mol K)
H_gh = -Tg.^2.*gradient(Gx./Tg,Tg);                             % Gibbs-Helmholtz
err_gh = max(abs(H_gh(5:end-5)-Hx(5:end-5)))/dH;
fprintf('(ii) Gibbs-Helmholtz balance check: max |H - (-T^2 d(G/T)/dT)| = %.2e of dH\n', err_gh);

%% --- Soliton figures ------------------------------------------------------------------
figure('Name','Soliton: PDE','Position',[40 40 1200 750]);
subplot(2,3,1); imagesc(xg*100, tt*1e3, U); axis xy; colorbar;
xlabel('x (cm)'); ylabel('t (ms)'); title('Pulse u(x,t) = \Delta\rho/\rho_0');
subplot(2,3,2); plot(xg*100,U(1,:),'--',xg*100,U(it1,:),'LineWidth',1.5);
legend('t = 0','t = 1 ms'); xlabel('x (cm)'); ylabel('u'); title('Density pulse'); grid on;
subplot(2,3,3); plot(xg*100,qA(it1,:),'r','LineWidth',1.5);
xlabel('x (cm)'); ylabel('mJ/m^2'); title('(ii) Heat released (+) / absorbed (-) at t = 1 ms'); grid on;
subplot(2,3,4); plot(tt*1e3,up,'k','LineWidth',1.5); xlabel('t (ms)'); ylabel('u');
title('Pulse passing fixed point x = 20 cm'); grid on;

% (i) pi-A diagram
subplot(2,3,5); hold on;
pg = linspace(10e-3,55e-3,500);
cols = lines(5); dTs = [-4 -2 0 2 4];
for k = 1:5
    Ak = (Ag + xf(T0+dTs(k),pg)*dA)*1e18/NA;      % nm^2 per lipid
    plot(Ak,pg*1e3,'Color',cols(k,:),'LineWidth',1.2);
end
plot(A_rev*1e18/NA,pi_rev*1e3,'k','LineWidth',2.5);
plot(A_irr*1e18/NA,pi_rev*1e3,'r','LineWidth',2);
xlabel('A (nm^2 / lipid)'); ylabel('\pi (mN/m)'); grid on;
title('(i) \pi-A diagram (2-D analogue of P-V)');
legend([arrayfun(@(d) sprintf('T_0%+d K',d),dTs,'UniformOutput',false), ...
        {'pulse, reversible','pulse, irreversible'}],'Location','northeast','FontSize',7);

% (ii) thermodynamic functions of the transition
subplot(2,3,6); yyaxis left;
plot(Tg-273.15,Hx*1e-3,Tg-273.15,Tg.*Sx*1e-3,Tg-273.15,Gx*1e-3,'LineWidth',1.3);
ylabel('kJ/mol'); yyaxis right; plot(Tg-273.15,cpx,'k--','LineWidth',1.3); ylabel('c_p excess (J/mol K)');
xlabel('T (\circC)'); legend('H','TS','G','c_p'); title('(ii) H, TS, G, c_p at \pi = \pi_{ref}'); grid on;

%% ========================================================================
%  LOCAL FUNCTIONS
%% ========================================================================
function dy = hh_rhs(~,y,Iapp,P)
    V = y(1); m = y(2); n = y(3); h = y(4);
    [am,bm,an,bn,ah,bh] = hh_rates(V);
    INa = P.gNa*m^3*h*(V-P.ENa);
    IK  = P.gK*n^4*(V-P.EK);
    IL  = P.gL*(V-P.EL);
    dy = [(Iapp - INa - IK - IL)/P.Cm;
          P.phi*(am*(1-m) - bm*m);
          P.phi*(an*(1-n) - bn*n);
          P.phi*(ah*(1-h) - bh*h)];
end

function [am,bm,an,bn,ah,bh] = hh_rates(V)
    am = 0.1*vtrap(V+40,10);
    bm = 4*exp(-(V+65)/18);
    an = 0.01*vtrap(V+55,10);
    bn = 0.125*exp(-(V+65)/80);
    ah = 0.07*exp(-(V+65)/20);
    bh = 1./(1+exp(-(V+35)/10));
end

function r = vtrap(x,y)
    % x/(1-exp(-x/y)) with the removable singularity at x = 0 handled
    r = x./(1-exp(-x./y));
    small = abs(x./y) < 1e-6;
    r(small) = y*(1 - x(small)./y/2);
end

function dy = soliton_rhs(y,kk,c0,p,q,hd,dealias,N)
    u  = y(1:N);  ut = y(N+1:end);
    f  = c0^2*u + p*u.^2/2 + q*u.^3/3;
    fh = fft(f).*dealias;
    uh = fft(u).*dealias;
    utt = real(ifft(-kk.^2.*fh - hd*kk.^4.*uh));
    dy = [ut; utt];
end